# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _check(students: Sequence[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for student in students:
        if not (student.email or "").strip():
            raise ProjectError(
                f"no email for {student.display_name}"
            )


def _line(cells: Tuple[str, ...], widths: List[int]) -> str:
    padded = (c.ljust(w) for c, w in zip(cells, widths))
    return "  ".join(padded).rstrip()


def _cells(people: List[Student]) -> List[Tuple[str, ...]]:
    return [
        (s.display_name, s.section, s.email.strip())
        for s in people
    ]


def _widths(cells: List[Tuple[str, ...]]) -> List[int]:
    return [max(len(v) for v in col) for col in zip(*cells)]


# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, by name."""
    people = sorted(
        students, key=lambda s: s.display_name.casefold()
    )
    _check(people)
    cells = _cells(people)
    widths = _widths(cells)
    return [_line(row, widths) for row in cells]
